import bcrypt from "bcryptjs";

const SALT_ROUNDS = 10;

export async function hashPassword(password: string): Promise<string> {
  return bcrypt.hash(password, SALT_ROUNDS);
}

export async function verifyPassword(password: string, hash: string): Promise<boolean> {
  return bcrypt.compare(password, hash);
}

import "server-only";
import { cookies } from "next/headers";
import { SignJWT, jwtVerify } from "jose";

const COOKIE_NAME = "homewise_session";
const SECRET = new TextEncoder().encode(
  process.env.AUTH_SECRET ?? "dev-secret-change-me-in-production-please-1234567890",
);

export interface SessionPayload {
  userId: string;
  email: string;
  role: string;
  plan: string;
}

export async function createSession(payload: SessionPayload): Promise<string> {
  const token = await new SignJWT(payload as unknown as Record<string, unknown>)
    .setProtectedHeader({ alg: "HS256" })
    .setIssuedAt()
    .setExpirationTime("30d")
    .sign(SECRET);
  return token;
}

export async function setSessionCookie(token: string) {
  const jar = await cookies();
  jar.set(COOKIE_NAME, token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite: "lax",
    path: "/",
    maxAge: 60 * 60 * 24 * 30,
  });
}

export async function getSession(): Promise<SessionPayload | null> {
  const jar = await cookies();
  const token = jar.get(COOKIE_NAME)?.value;
  if (!token) return null;
  try {
    const { payload } = await jwtVerify(token, SECRET);
    return payload as unknown as SessionPayload;
  } catch {
    return null;
  }
}

export async function clearSession() {
  const jar = await cookies();
  jar.delete(COOKIE_NAME);
}

export { COOKIE_NAME };

import "server-only";
import { prisma } from "@/lib/db/prisma";
import { getSession } from "@/lib/auth/session";

export async function getCurrentUser() {
  const session = await getSession();
  if (!session) return null;
  const user = await prisma.user.findUnique({ where: { id: session.userId } });
  return user;
}

export async function requireUser() {
  const user = await getCurrentUser();
  if (!user) throw new Error("UNAUTHORIZED");
  return user;
}

export async function requireAdmin() {
  const user = await requireUser();
  if (user.role !== "ADMIN") throw new Error("FORBIDDEN");
  return user;
}

import { z } from "zod";

export const registerSchema = z.object({
  name: z.string().min(1).max(80).optional(),
  email: z.string().email().max(200),
  password: z.string().min(8).max(128),
});

export const loginSchema = z.object({
  email: z.string().email(),
  password: z.string().min(1),
});

import { z } from "zod";

export const expenseSchema = z.object({
  householdId: z.string().min(1),
  categoryId: z.string().min(1),
  amount: z.coerce.number().positive().max(100000000),
  date: z.string().min(1),
  notes: z.string().max(500).optional().or(z.literal("")),
  paymentMethod: z.enum(["CASH", "CARD", "UPI", "BANK", "WALLET", "OTHER"]).default("CASH"),
  isRecurring: z.coerce.boolean().optional().default(false),
  recurringFreq: z.enum(["DAILY", "WEEKLY", "MONTHLY", "YEARLY"]).optional().nullable(),
});

export const budgetSchema = z.object({
  householdId: z.string().min(1),
  categoryId: z.string().optional().nullable(),
  amount: z.coerce.number().positive().max(100000000),
  period: z.enum(["MONTHLY", "YEARLY"]).default("MONTHLY"),
  month: z.coerce.number().int().min(1).max(12).optional().nullable(),
  year: z.coerce.number().int().min(2000).max(2100),
});

import { z } from "zod";

export const householdSchema = z.object({
  name: z.string().min(1).max(80),
  currency: z.string().min(3).max(5).default("INR"),
});

