1: /**
2:  * In-memory fixed-window rate limiter.
3:  *
4:  * This is a correct single-instance foundation and prevents accidental abuse
5:  * during development. For horizontal scaling, swap the Map for Redis/Upstash
6:  * using the same interface.
7:  */
8: interface RateLimitEntry {
9:   count: number;
10:   resetAt: number;
11: }
12: 
13: const buckets = new Map<string, RateLimitEntry>();
14: const MAX_TRACKED_KEYS = 10_000;
15: 
16: export interface RateLimitOptions {
17:   limit: number;
18:   windowMs: number;
19: }
20: 
21: export interface RateLimitResult {
22:   success: boolean;
23:   limit: number;
24:   remaining: number;
25:   resetAt: number;
26: }
27: 
28: function pruneExpired(now: number) {
29:   for (const [key, entry] of buckets) {
30:     if (entry.resetAt <= now) buckets.delete(key);
31:   }
32: 
33:   if (buckets.size >= MAX_TRACKED_KEYS) {
34:     const overflow = buckets.size - MAX_TRACKED_KEYS + 500;
35:     let removed = 0;
36:     for (const key of buckets.keys()) {
37:       buckets.delete(key);
38:       if (++removed >= overflow) break;
39:     }
40:   }
41: }
42: 
43: export function checkRateLimit(key: string, options: RateLimitOptions): RateLimitResult {
44:   const now = Date.now();
45: 
46:   if (buckets.size >= MAX_TRACKED_KEYS) pruneExpired(now);
47: 
48:   const existing = buckets.get(key);
49: 
50:   if (!existing || existing.resetAt <= now) {
51:     const resetAt = now + options.windowMs;
52:     buckets.set(key, { count: 1, resetAt });
53:     return { success: true, limit: options.limit, remaining: options.limit - 1, resetAt };
54:   }
55: 
56:   existing.count += 1;
57:   const remaining = Math.max(0, options.limit - existing.count);
58: 
59:   return {
60:     success: existing.count <= options.limit,
61:     limit: options.limit,
62:     remaining,
63:     resetAt: existing.resetAt,
64:   };
65: }
66: 
67: export function getClientIp(headers: Headers): string {
68:   const forwarded = headers.get("x-forwarded-for");
69:   if (forwarded) {
70:     const first = forwarded.split(",")[0]?.trim();
71:     if (first) return first;
72:   }
73: 
