23: /**
24:  * Wraps a Route Handler with request IDs, structured logging, rate limiting,
25:  * CORS allow-listing, and consistent error responses.
26:  */
27: export function createApiHandler<TParams = Record<string, string>>(
28:   handler: (request: NextRequest, context: ApiHandlerContext<TParams>) => Promise<Response>,
29:   options: ApiHandlerOptions = {},
30: ) {
31:   return async (request: NextRequest, routeContext?: RouteContext<TParams>): Promise<Response> => {
32:     const startedAt = Date.now();
33:     const incomingRequestId = request.headers.get(REQUEST_ID_HEADER);
34:     const requestId =
35:       incomingRequestId && /^[A-Za-z0-9_-]{8,128}$/.test(incomingRequestId)
36:         ? incomingRequestId
37:         : crypto.randomUUID();
38: 
39:     const log = createRequestLogger(requestId, {
40:       method: request.method,
41:       path: request.nextUrl.pathname,
42:     });
43: 
44:     const origin = getAllowedOrigin(request.headers.get("origin"));
45: 
46:     try {
47:       if (options.rateLimit !== false) {
48:         const env = getServerEnv();
49:         const limit = options.rateLimit?.limit ?? env.RATE_LIMIT_MAX_REQUESTS;
50:         const windowMs = options.rateLimit?.windowMs ?? env.RATE_LIMIT_WINDOW_MS;
51:         const result = checkRateLimit(
52:           `${getClientIp(request.headers)}:${request.nextUrl.pathname}`,
53:           {
54:             limit,
55:             windowMs,
56:           },
57:         );
58: 
59:         if (!result.success) {
60:           throw new RateLimitError(Math.max(1, Math.ceil((result.resetAt - Date.now()) / 1000)));
61:         }
62:       }
