66: 
67:       response.headers.set(REQUEST_ID_HEADER, requestId);
68:       response.headers.set("Cache-Control", options.cacheControl ?? "no-store");
69:       if (origin) {
70:         for (const [key, value] of Object.entries(getCorsHeaders(origin))) {
71:           response.headers.set(key, value);
72:         }
73:       }
74: 
75:       log.info(
76:         { status: response.status, durationMs: Date.now() - startedAt },
77:         "request.completed",
78:       );
79: 
80:       return response;
81:     } catch (error) {
82:       const appError = normalizeError(error);
83: 
84:       log[appError.status >= 500 ? "error" : "warn"](
