import { registerSchema } from "@/lib/validation/auth";
import { z } from "zod";

export async function POST(req: Request) {
  try {
    const body = await req.json();
    const data = registerSchema.parse(body);
    const existing = await prisma.user.findUnique({ where: { email: data.email } });
    if (existing) return NextResponse.json({ error: { message: "Email already registered" } }, { status: 409 });
    const user = await prisma.user.create({
      data: {
        email: data.email,
        name: data.name,
        passwordHash: await hashPassword(data.password),
      },
    });
    // create default household
    const hh = await prisma.household.create({ data: { name: `${data.name ?? "My"} Household`, ownerId: user.id } });
    await prisma.householdMember.create({ data: { householdId: hh.id, userId: user.id, role: "OWNER" } });
    const token = await createSession({ userId: user.id, email: user.email, role: user.role, plan: user.plan });
    await setSessionCookie(token);
    return NextResponse.json({ success: true, data: { id: user.id, email: user.email } });
  } catch (err) {
    if (err instanceof z.ZodError) {
      return NextResponse.json({ error: { message: err.issues[0]?.message ?? "Invalid input" } }, { status: 400 });
    }
    console.error(err);
    return NextResponse.json({ error: { message: "Registration failed" } }, { status: 500 });
  }
}

