import { NextResponse } from "next/server";
import { prisma } from "@/lib/db/prisma";
import { getCurrentUser } from "@/lib/auth/current-user";
import { expenseSchema } from "@/lib/validation/expense";

export async function GET(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  const url = new URL(req.url);
  const householdId = url.searchParams.get("householdId");
  const membership = await prisma.householdMember.findFirst({ where: { userId: user.id, ...(householdId ? { householdId } : {}) } });
  if (!membership) return NextResponse.json({ error: { message: "No household" } }, { status: 400 });
  const hid = membership.householdId;
  const categoryId = url.searchParams.get("categoryId");
  const from = url.searchParams.get("from");
  const to = url.searchParams.get("to");
  const q = url.searchParams.get("q");
  const expenses = await prisma.expense.findMany({
    where: {
      householdId: hid,
      ...(categoryId ? { categoryId } : {}),
      ...(from || to ? { date: { ...(from ? { gte: new Date(from) } : {}), ...(to ? { lte: new Date(to) } : {}) } } : {}),
      ...(q ? { OR: [{ notes: { contains: q } }] } : {}),
    },
    include: { category: true, user: { select: { id: true, name: true, email: true } } },
    orderBy: { date: "desc" },
    take: 500,
  });
  return NextResponse.json({ success: true, data: expenses });
}

export async function POST(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  try {
    const body = await req.json();
    const data = expenseSchema.parse(body);
    // verify membership
    const membership = await prisma.householdMember.findFirst({ where: { userId: user.id, householdId: data.householdId } });
    if (!membership) return NextResponse.json({ error: { message: "Not a member of household" } }, { status: 403 });
    const expense = await prisma.expense.create({
      data: {
        householdId: data.householdId,
        userId: user.id,
        categoryId: data.categoryId,
        amount: data.amount,
        date: new Date(data.date),
        notes: data.notes || null,
        paymentMethod: data.paymentMethod,
        isRecurring: data.isRecurring ?? false,
        recurringFreq: data.recurringFreq ?? null,
      },
      include: { category: true },
    });
    return NextResponse.json({ success: true, data: expense }, { status: 201 });
  } catch (err) {
    const msg = err instanceof Error ? err.message : "Invalid input";
    return NextResponse.json({ error: { message: msg } }, { status: 400 });
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/db/prisma";
import { getCurrentUser } from "@/lib/auth/current-user";
import { expenseSchema } from "@/lib/validation/expense";

export async function GET(_req: Request, ctx: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  const { id } = await ctx.params;
  const expense = await prisma.expense.findUnique({ where: { id }, include: { category: true } });
  if (!expense) return NextResponse.json({ error: { message: "Not found" } }, { status: 404 });
  const membership = await prisma.householdMember.findFirst({ where: { userId: user.id, householdId: expense.householdId } });
  if (!membership) return NextResponse.json({ error: { message: "Forbidden" } }, { status: 403 });
  return NextResponse.json({ success: true, data: expense });
}

export async function PATCH(req: Request, ctx: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  const { id } = await ctx.params;
  const expense = await prisma.expense.findUnique({ where: { id } });
  if (!expense) return NextResponse.json({ error: { message: "Not found" } }, { status: 404 });
  const membership = await prisma.householdMember.findFirst({ where: { userId: user.id, householdId: expense.householdId } });
  if (!membership) return NextResponse.json({ error: { message: "Forbidden" } }, { status: 403 });
  try {
    const body = await req.json();
    const data = expenseSchema.partial().parse(body);
    const updated = await prisma.expense.update({
      where: { id },
      data: {
        ...(data.categoryId ? { categoryId: data.categoryId } : {}),
        ...(data.amount !== undefined ? { amount: data.amount } : {}),
        ...(data.date ? { date: new Date(data.date) } : {}),
        ...(data.notes !== undefined ? { notes: data.notes || null } : {}),
        ...(data.paymentMethod ? { paymentMethod: data.paymentMethod } : {}),
        ...(data.isRecurring !== undefined ? { isRecurring: data.isRecurring } : {}),
        ...(data.recurringFreq !== undefined ? { recurringFreq: data.recurringFreq } : {}),
      },
      include: { category: true },
    });
    return NextResponse.json({ success: true, data: updated });
  } catch (err) {
    return NextResponse.json({ error: { message: err instanceof Error ? err.message : "Invalid input" } }, { status: 400 });
  }
}

