import { NextResponse } from "next/server";
import { prisma } from "@/lib/db/prisma";
import { getCurrentUser } from "@/lib/auth/current-user";

export async function GET(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  const url = new URL(req.url);
  const householdId = url.searchParams.get("householdId");
  if (!householdId) return NextResponse.json({ error: { message: "householdId required" } }, { status: 400 });
  const membership = await prisma.householdMember.findFirst({ where: { userId: user.id, householdId } });
  if (!membership) return NextResponse.json({ error: { message: "Forbidden" } }, { status: 403 });

  const now = new Date();
  const year = Number(url.searchParams.get("year") ?? now.getFullYear());
  const month = Number(url.searchParams.get("month") ?? (now.getMonth() + 1));
  const start = new Date(year, month - 1, 1);
  const end = new Date(year, month, 0, 23, 59, 59);

  const expenses = await prisma.expense.findMany({
    where: { householdId, date: { gte: start, lte: end } },
    include: { category: true },
  });

  const total = expenses.reduce((s, e) => s + Number(e.amount), 0);
  const byCategory: Record<string, { name: string; color: string; amount: number }> = {};
  for (const e of expenses) {
    const key = e.categoryId;
    if (!byCategory[key]) byCategory[key] = { name: e.category.name, color: e.category.color, amount: 0 };
    byCategory[key].amount += Number(e.amount);
  }
  const categoryList = Object.values(byCategory).sort((a, b) => b.amount - a.amount);

  // last 6 months trend
  const trend: { month: string; amount: number }[] = [];
  for (let i = 5; i >= 0; i--) {
    const d = new Date(year, month - 1 - i, 1);
    const s = new Date(d.getFullYear(), d.getMonth(), 1);
    const e = new Date(d.getFullYear(), d.getMonth() + 1, 0, 23, 59, 59);
    const ex = await prisma.expense.findMany({ where: { householdId, date: { gte: s, lte: e } } });
    trend.push({ month: s.toLocaleString("default", { month: "short" }), amount: ex.reduce((x, y) => x + Number(y.amount), 0) });
  }

  // budgets
  const budgets = await prisma.budget.findMany({ where: { householdId, year, month }, include: { category: true } });
  const budgetStatus = budgets.map((b) => {
    const spent = b.categoryId ? (byCategory[b.categoryId]?.amount ?? 0) : total;
    return { id: b.id, category: b.category?.name ?? "Overall", amount: Number(b.amount), spent, percent: Number(b.amount) > 0 ? (spent / Number(b.amount)) * 100 : 0 };
  });

  return NextResponse.json({ success: true, data: { total, count: expenses.length, byCategory: categoryList, trend, budgetStatus, month, year } });
}

