import { NextResponse } from "next/server";
import { prisma } from "@/lib/db/prisma";
import { getCurrentUser } from "@/lib/auth/current-user";

export async function POST(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  const body = await req.json().catch(() => ({}));
  const plan = body?.plan === "FREE" ? "FREE" : "PREMIUM";
  if (plan === "PREMIUM") {
    const sub = await prisma.subscription.create({
      data: {
        userId: user.id,
        plan: "PREMIUM",
        status: "ACTIVE",
        provider: "mock",
        externalId: "mock_" + Date.now(),
        currentPeriodStart: new Date(),
        currentPeriodEnd: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000),
      },
    });
    await prisma.payment.create({
      data: { userId: user.id, subscriptionId: sub.id, amount: 499, currency: "INR", status: "succeeded", provider: "mock", externalId: sub.externalId },
    });
  }
  const updated = await prisma.user.update({ where: { id: user.id }, data: { plan } });
  // if downgrade, cancel subs
  if (plan === "FREE") {
    await prisma.subscription.updateMany({ where: { userId: user.id, status: "ACTIVE" }, data: { status: "CANCELLED" } });
  }
  return NextResponse.json({ success: true, data: { plan: updated.plan } });
}

