"use client";
import { useEffect, useState } from "react";

interface Household { id: string; name: string; currency: string; }
interface Category { id: string; name: string; color: string; householdId: string | null; }
interface Expense { id: string; amount: string; date: string; notes: string | null; paymentMethod: string; categoryId: string; category: { name: string; color: string }; }

const paymentMethods = ["CASH", "CARD", "UPI", "BANK", "WALLET", "OTHER"];

export default function ExpensesView() {
  const [households, setHouseholds] = useState<Household[]>([]);
  const [active, setActive] = useState("");
  const [categories, setCategories] = useState<Category[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [showForm, setShowForm] = useState(false);
  const [editing, setEditing] = useState<Expense | null>(null);
  const [form, setForm] = useState({ categoryId: "", amount: "", date: new Date().toISOString().slice(0, 10), notes: "", paymentMethod: "CASH" });
  const [filterCat, setFilterCat] = useState("");
  const [q, setQ] = useState("");

  async function loadHouseholds() {
    const h = await fetch("/api/households").then((r) => r.json());
    const list = h.data ?? [];
    setHouseholds(list);
    if (list.length && !active) setActive(list[0].id);
  }
  async function loadCategories(hid: string) {
    const c = await fetch(`/api/categories?householdId=${hid}`).then((r) => r.json());
    setCategories(c.data ?? []);
  }
  async function loadExpenses(hid: string) {
    const params = new URLSearchParams({ householdId: hid });
    if (filterCat) params.set("categoryId", filterCat);
    if (q) params.set("q", q);
    const e = await fetch(`/api/expenses?${params}`).then((r) => r.json());
    setExpenses(e.data ?? []);
  }

  useEffect(() => { loadHouseholds(); }, []);
  useEffect(() => { if (active) { loadCategories(active); loadExpenses(active); } }, [active]);
  useEffect(() => { if (active) loadExpenses(active); }, [filterCat, q]);

  function openNew() {
    setEditing(null);
    setForm({ categoryId: categories[0]?.id ?? "", amount: "", date: new Date().toISOString().slice(0, 10), notes: "", paymentMethod: "CASH" });
    setShowForm(true);
  }
  function openEdit(e: Expense) {
    setEditing(e);
    setForm({ categoryId: e.categoryId, amount: e.amount, date: e.date.slice(0, 10), notes: e.notes ?? "", paymentMethod: e.paymentMethod });
    setShowForm(true);
  }

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    const payload = { householdId: active, ...form, amount: Number(form.amount), isRecurring: false };
    const url = editing ? `/api/expenses/${editing.id}` : "/api/expenses";
    const method = editing ? "PATCH" : "POST";
    const res = await fetch(url, { method, headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) });
    if (res.ok) { setShowForm(false); loadExpenses(active); }
    else { const j = await res.json(); alert(j?.error?.message ?? "Failed"); }
  }
  async function remove(id: string) {
    if (!confirm("Delete this expense?")) return;
    await fetch(`/api/expenses/${id}`, { method: "DELETE" });
    loadExpenses(active);
  }

  if (!households.length) return <div className="p-8">No household. <a href="/household" className="text-indigo-600">Create one</a></div>;

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <h1 className="text-2xl font-bold">Expenses</h1>
        <div className="flex gap-2">
