import "dotenv/config";
import { PrismaBetterSqlite3 } from "@prisma/adapter-better-sqlite3";
import { PrismaClient } from "../src/generated/prisma/client.js";
import bcrypt from "bcryptjs";

const prisma = new PrismaClient({ adapter: new PrismaBetterSqlite3({ url: process.env.DATABASE_URL! }) });

const defaultCategories = [
  { name: "Housing", slug: "housing", color: "#6366f1", icon: "home", subs: ["House rent","Home loan EMI","Property tax","Maintenance charges","Society charges","Home insurance","Repairs","Interior decoration","Furniture","Painting","Plumbing","Electrical repairs"] },
  { name: "Food & Groceries", slug: "food-groceries", color: "#22c55e", icon: "shopping-cart", subs: ["Vegetables","Fruits","Milk","Dairy products","Rice and wheat","Groceries","Cooking oil","Snacks","Beverages","Restaurant","Food delivery","Drinking water"] },
  { name: "Utilities", slug: "utilities", color: "#eab308", icon: "zap", subs: ["Electricity","Water bill","Gas cylinder","Piped gas","Internet","Wi-Fi","Mobile recharge","Cable TV","DTH","Garbage collection"] },
  { name: "Transportation", slug: "transportation", color: "#3b82f6", icon: "car", subs: ["Petrol","Diesel","Public transport","Bus","Train","Taxi","Auto-rickshaw","Vehicle EMI","Vehicle insurance","Vehicle maintenance","Parking","Toll charges"] },
  { name: "Healthcare", slug: "healthcare", color: "#ef4444", icon: "heart", subs: ["Doctor consultation","Medicines","Hospital expenses","Medical tests","Health insurance","Dental care","Eye care","Emergency medical expenses"] },
  { name: "Education", slug: "education", color: "#8b5cf6", icon: "book", subs: ["School fees","College fees","Tuition","Books","Stationery","Online courses","Examination fees","Coaching classes"] },
  { name: "Personal Expenses", slug: "personal", color: "#ec4899", icon: "user", subs: ["Clothing","Shoes","Grooming","Cosmetics","Haircuts","Personal care","Accessories"] },
  { name: "Family & Children", slug: "family-children", color: "#f97316", icon: "users", subs: ["Childcare","Baby products","Toys","School activities","Family outings","Elderly care","Pocket money"] },
  { name: "Entertainment & Lifestyle", slug: "entertainment", color: "#14b8a6", icon: "film", subs: ["Movies","OTT subscriptions","Gaming","Sports","Hobbies","Travel","Vacations","Events","Restaurants"] },
  { name: "Financial Obligations", slug: "financial", color: "#64748b", icon: "credit-card", subs: ["Personal loan EMI","Credit card payments","Loan interest","Bank charges","Investment contributions","Savings deposits","Emergency fund contributions"] },
  { name: "Household Services", slug: "household-services", color: "#a855f7", icon: "briefcase", subs: ["Maid salary","Cook salary","Driver salary","Security","Laundry","Pest control","Cleaning services"] },
  { name: "Pet Expenses", slug: "pet", color: "#84cc16", icon: "paw", subs: ["Pet food","Veterinary","Vaccination","Grooming","Pet accessories"] },
  { name: "Occasional Expenses", slug: "occasional", color: "#f59e0b", icon: "gift", subs: ["Festivals","Weddings","Religious ceremonies","Birthday celebrations","Gifts","Donations","Unexpected purchases"] },
  { name: "Miscellaneous", slug: "miscellaneous", color: "#94a3b8", icon: "more-horizontal", subs: ["Custom user-created categories","Uncategorized expenses"] },
];

async function main() {
  for (const c of defaultCategories) {
    const existing = await prisma.category.findFirst({ where: { householdId: null, slug: c.slug } });
    if (!existing) {
      await prisma.category.create({ data: { householdId: null, name: c.name, slug: c.slug, color: c.color, icon: c.icon, isDefault: true, type: "EXPENSE" } });
    }
    for (const sub of c.subs) {
      const subSlug = `${c.slug}-${sub.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "")}`;
      const existingSub = await prisma.category.findFirst({ where: { householdId: null, slug: subSlug } });
      if (!existingSub) {
        await prisma.category.create({ data: { householdId: null, name: sub, slug: subSlug, color: c.color, icon: c.icon, isDefault: true, type: "EXPENSE" } });
      }
    }
  }

  const adminHash = await bcrypt.hash("Admin@123", 10);
  await prisma.user.upsert({
    where: { email: "admin@homewise.local" },
    update: {},
    create: { email: "admin@homewise.local", name: "Admin", passwordHash: adminHash, role: "ADMIN", plan: "PREMIUM" },
  });

  const demoHash = await bcrypt.hash("Demo@1234", 10);
  const demo = await prisma.user.upsert({
    where: { email: "demo@homewise.local" },
    update: {},
    create: { email: "demo@homewise.local", name: "Demo User", passwordHash: demoHash, role: "USER", plan: "FREE" },
  });

  const existingHh = await prisma.household.findFirst({ where: { ownerId: demo.id } });
  let hh = existingHh;
  if (!hh) {
    hh = await prisma.household.create({ data: { name: "Demo Household", currency: "INR", ownerId: demo.id } });
    await prisma.householdMember.create({ data: { householdId: hh.id, userId: demo.id, role: "OWNER" } });
  }

  console.log("Seed complete");
}

main().then(() => prisma.$disconnect()).catch((e) => { console.error(e); process.exit(1); });

