import { NextResponse } from "next/server";
import { prisma } from "@/lib/db/prisma";
import { getCurrentUser } from "@/lib/auth/current-user";
import { z } from "zod";

const incomeSchema = z.object({
  householdId: z.string().min(1),
  amount: z.coerce.number().positive().max(100000000),
  date: z.string().min(1),
  source: z.string().max(120).optional().or(z.literal("")),
  notes: z.string().max(500).optional().or(z.literal("")),
  isRecurring: z.coerce.boolean().optional().default(false),
});

export async function GET(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  const url = new URL(req.url);
  const householdId = url.searchParams.get("householdId");
  if (!householdId) return NextResponse.json({ error: { message: "householdId required" } }, { status: 400 });
  const membership = await prisma.householdMember.findFirst({ where: { userId: user.id, householdId } });
  if (!membership) return NextResponse.json({ error: { message: "Forbidden" } }, { status: 403 });
  const incomes = await prisma.income.findMany({ where: { householdId }, orderBy: { date: "desc" }, take: 500 });
  return NextResponse.json({ success: true, data: incomes });
}

export async function POST(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  try {
    const data = incomeSchema.parse(await req.json());
    const membership = await prisma.householdMember.findFirst({ where: { userId: user.id, householdId: data.householdId } });
    if (!membership) return NextResponse.json({ error: { message: "Forbidden" } }, { status: 403 });
    const income = await prisma.income.create({
      data: {
        householdId: data.householdId,
        userId: user.id,
        amount: data.amount,
        date: new Date(data.date),
        source: data.source || null,
        notes: data.notes || null,
        isRecurring: data.isRecurring ?? false,
      },
    });
    return NextResponse.json({ success: true, data: income }, { status: 201 });
  } catch (err) {
    return NextResponse.json({ error: { message: err instanceof Error ? err.message : "Invalid" } }, { status: 400 });
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/db/prisma";
import { getCurrentUser } from "@/lib/auth/current-user";

export async function GET(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  const url = new URL(req.url);
  const householdId = url.searchParams.get("householdId");
  if (!householdId) return NextResponse.json({ error: { message: "householdId required" } }, { status: 400 });
  const membership = await prisma.householdMember.findFirst({ where: { userId: user.id, householdId } });
  if (!membership) return NextResponse.json({ error: { message: "Forbidden" } }, { status: 403 });

  const now = new Date();
  const year = Number(url.searchParams.get("year") ?? now.getFullYear());
  const month = Number(url.searchParams.get("month") ?? (now.getMonth() + 1));
  const daysInMonth = new Date(year, month, 0).getDate();
  const start = new Date(year, month - 1, 1);
  const end = new Date(year, month, 0, 23, 59, 59);

  const expenses = await prisma.expense.findMany({
    where: { householdId, date: { gte: start, lte: end } },
    include: { category: true },
    orderBy: { date: "desc" },
  });
  const incomes = await prisma.income.findMany({
    where: { householdId, date: { gte: start, lte: end } },
  });

  const total = expenses.reduce((s, e) => s + Number(e.amount), 0);
  const totalIncome = incomes.reduce((s, i) => s + Number(i.amount), 0);
  const savings = totalIncome - total;
  const savingsRate = totalIncome > 0 ? (savings / totalIncome) * 100 : 0;
  const dailyAvg = total / daysInMonth;

  const byCategory: Record<string, { name: string; color: string; amount: number }> = {};
  for (const e of expenses) {
    const key = e.categoryId;
    if (!byCategory[key]) byCategory[key] = { name: e.category.name, color: e.category.color, amount: 0 };
    byCategory[key].amount += Number(e.amount);
  }
  const categoryList = Object.values(byCategory).sort((a, b) => b.amount - a.amount);
  const top5 = categoryList.slice(0, 5);

  const fixed = expenses.filter((e) => e.isFixed).reduce((s, e) => s + Number(e.amount), 0);
  const variable = total - fixed;
  const essential = expenses.filter((e) => e.isEssential).reduce((s, e) => s + Number(e.amount), 0);
  const nonEssential = total - essential;

  // last 6 months trend
  const trend: { month: string; amount: number; income: number }[] = [];
  for (let i = 5; i >= 0; i--) {
    const d = new Date(year, month - 1 - i, 1);
    const s = new Date(d.getFullYear(), d.getMonth(), 1);
    const e = new Date(d.getFullYear(), d.getMonth() + 1, 0, 23, 59, 59);
    const ex = await prisma.expense.findMany({ where: { householdId, date: { gte: s, lte: e } } });
    const inc = await prisma.income.findMany({ where: { householdId, date: { gte: s, lte: e } } });
    trend.push({
      month: s.toLocaleString("default", { month: "short" }),
      amount: ex.reduce((x, y) => x + Number(y.amount), 0),
      income: inc.reduce((x, y) => x + Number(y.amount), 0),
    });
  }

  // budgets
  const budgets = await prisma.budget.findMany({ where: { householdId, year, month }, include: { category: true } });
  const budgetStatus = budgets.map((b) => {
    const spent = b.categoryId ? (byCategory[b.categoryId]?.amount ?? 0) : total;
    return { id: b.id, category: b.category?.name ?? "Overall", amount: Number(b.amount), spent, percent: Number(b.amount) > 0 ? (spent / Number(b.amount)) * 100 : 0 };
  });
  const remainingBudget = budgets.length ? budgets.reduce((s, b) => s + Number(b.amount), 0) - total : 0;

  // upcoming recurring (next 30 days)
  const upcoming = expenses
    .filter((e) => e.isRecurring)
    .slice(0, 10)
    .map((e) => ({ id: e.id, date: e.date, amount: Number(e.amount), category: e.category.name, freq: e.recurringFreq }));

  // recent transactions (last 10)
  const recent = expenses.slice(0, 10).map((e) => ({ id: e.id, date: e.date, amount: Number(e.amount), category: e.category.name, color: e.category.color, notes: e.notes, paymentMethod: e.paymentMethod }));

  // yearly projection
  const monthlyAvg = total; // current month
  const yearlyProjection = monthlyAvg * 12;

  return NextResponse.json({
    success: true,
    data: {
      total, totalIncome, savings, savingsRate, dailyAvg, count: expenses.length,
      byCategory: categoryList, top5, trend, budgetStatus, remainingBudget,
      fixed, variable, essential, nonEssential,
      upcoming, recent, yearlyProjection, month, year, daysInMonth,
    },
  });
}

"use client";
import { useEffect, useState } from "react";

interface Household { id: string; name: string; }

