"use client";
import { useEffect, useState } from "react";
import Link from "next/link";

interface Household { id: string; name: string; currency: string; }

const DATE_FILTERS = [
  { key: "today", label: "Today" },
  { key: "week", label: "This week" },
  { key: "month", label: "This month" },
  { key: "lastmonth", label: "Last month" },
  { key: "3m", label: "Last 3 months" },
  { key: "6m", label: "Last 6 months" },
  { key: "year", label: "This year" },
];

function dateRange(key: string) {
  const now = new Date();
  let from = new Date(now);
  let to = new Date(now);
  switch (key) {
    case "today":
      from.setHours(0, 0, 0, 0); to.setHours(23, 59, 59, 999); break;
    case "week": {
      const day = now.getDay();
      from.setDate(now.getDate() - day); from.setHours(0, 0, 0, 0);
      to.setDate(from.getDate() + 6); to.setHours(23, 59, 59, 999); break;
    }
    case "month":
      from = new Date(now.getFullYear(), now.getMonth(), 1);
      to = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59); break;
    case "lastmonth":
      from = new Date(now.getFullYear(), now.getMonth() - 1, 1);
      to = new Date(now.getFullYear(), now.getMonth(), 0, 23, 59, 59); break;
    case "3m":
      from = new Date(now.getFullYear(), now.getMonth() - 2, 1);
      to = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59); break;
    case "6m":
      from = new Date(now.getFullYear(), now.getMonth() - 5, 1);
      to = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59); break;
    case "year":
      from = new Date(now.getFullYear(), 0, 1);
      to = new Date(now.getFullYear(), 11, 31, 23, 59, 59); break;
  }
  return { from, to, year: to.getFullYear(), month: to.getMonth() + 1 };
}

export default function DashboardView() {
  const [households, setHouseholds] = useState<Household[]>([]);
  const [active, setActive] = useState("");
  const [filter, setFilter] = useState("month");
  const [summary, setSummary] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    (async () => {
      const h = await fetch("/api/households").then((r) => r.json());
      const list = h.data ?? [];
      setHouseholds(list);
      if (list.length) setActive(list[0].id);
      setLoading(false);
    })();
  }, []);

  useEffect(() => {
    if (!active) return;
    const { year, month } = dateRange(filter);
    fetch(`/api/analytics/summary?householdId=${active}&year=${year}&month=${month}`)
      .then((r) => r.json()).then((j) => setSummary(j.data));
  }, [active, filter]);

  if (loading) return <div className="p-8 text-slate-500">Loading...</div>;
  if (!households.length) return <div className="p-8">No household yet. <Link href="/household" className="text-indigo-600">Create one</Link></div>;

  const s = summary;
  return (
