"use client";
import { useEffect, useState } from "react";

interface Household { id: string; name: string; }
interface Income { id: string; amount: string; date: string; source: string | null; notes: string | null; isRecurring: boolean; }

export default function IncomeView() {
  const [households, setHouseholds] = useState<Household[]>([]);
  const [active, setActive] = useState("");
  const [incomes, setIncomes] = useState<Income[]>([]);
  const [form, setForm] = useState({ amount: "", date: new Date().toISOString().slice(0, 10), source: "", notes: "", isRecurring: false });
  const [show, setShow] = useState(false);

  useEffect(() => {
    (async () => {
      const h = await fetch("/api/households").then((r) => r.json());
      const list = h.data ?? [];
      setHouseholds(list);
      if (list.length) setActive(list[0].id);
    })();
  }, []);
  useEffect(() => { if (active) load(); }, [active]);

  async function load() {
    const r = await fetch(`/api/incomes?householdId=${active}`).then((r) => r.json());
    setIncomes(r.data ?? []);
  }
  async function submit(e: React.FormEvent) {
    e.preventDefault();
    const res = await fetch("/api/incomes", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ householdId: active, ...form, amount: Number(form.amount) }) });
    if (res.ok) { setShow(false); setForm({ amount: "", date: new Date().toISOString().slice(0, 10), source: "", notes: "", isRecurring: false }); load(); }
    else { const j = await res.json(); alert(j?.error?.message ?? "Failed"); }
  }
  async function remove(id: string) {
    if (!confirm("Delete?")) return;
    await fetch(`/api/incomes/${id}`, { method: "DELETE" });
    load();
  }

  if (!households.length) return <div className="p-8">No household.</div>;

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold">Income</h1>
        <div className="flex gap-2">
          <select value={active} onChange={(e) => setActive(e.target.value)} className="rounded-lg border px-3 py-2 text-sm">
            {households.map((h) => <option key={h.id} value={h.id}>{h.name}</option>)}
          </select>
          <button onClick={() => setShow(true)} className="rounded-lg bg-green-600 px-4 py-2 text-sm font-medium text-white">+ Add Income</button>
        </div>
      </div>
      {show && (
        <div className="rounded-2xl bg-white p-6 shadow-sm">
          <form onSubmit={submit} className="grid gap-4 sm:grid-cols-2">
            <div>
              <label className="text-sm font-medium">Amount</label>
              <input type="number" step="0.01" required value={form.amount} onChange={(e) => setForm({ ...form, amount: e.target.value })} className="mt-1 w-full rounded-lg border px-3 py-2" />
            </div>
            <div>
              <label className="text-sm font-medium">Date</label>
              <input type="date" required value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} className="mt-1 w-full rounded-lg border px-3 py-2" />
            </div>
            <div>
              <label className="text-sm font-medium">Source</label>
              <input value={form.source} onChange={(e) => setForm({ ...form, source: e.target.value })} className="mt-1 w-full rounded-lg border px-3 py-2" />
            </div>
            <div>
              <label className="text-sm font-medium">Notes</label>
              <input value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} className="mt-1 w-full rounded-lg border px-3 py-2" />
            </div>
            <div className="sm:col-span-2 flex gap-2">
              <button className="rounded-lg bg-green-600 px-4 py-2 text-sm font-medium text-white">Save</button>
              <button type="button" onClick={() => setShow(false)} className="rounded-lg border px-4 py-2 text-sm">Cancel</button>
            </div>
          </form>
        </div>
      )}
      <div className="rounded-2xl bg-white shadow-sm overflow-x-auto">
        <table className="w-full text-sm">
          <thead className="border-b bg-slate-50 text-left">
            <tr>
              <th className="px-4 py-3">Date</th>
              <th className="px-4 py-3">Source</th>
              <th className="px-4 py-3">Amount</th>
              <th className="px-4 py-3">Notes</th>
              <th className="px-4 py-3"></th>
            </tr>
          </thead>
          <tbody>
            {incomes.map((i) => (
              <tr key={i.id} className="border-b last:border-0">
                <td className="px-4 py-3">{i.date.slice(0, 10)}</td>
                <td className="px-4 py-3">{i.source ?? "-"}</td>
                <td className="px-4 py-3 font-medium text-green-600">₹{Number(i.amount).toLocaleString()}</td>
                <td className="px-4 py-3 text-slate-500">{i.notes}</td>
                <td className="px-4 py-3 text-right"><button onClick={() => remove(i.id)} className="text-red-600 hover:underline">Delete</button></td>
              </tr>
            ))}
            {incomes.length === 0 && <tr><td colSpan={5} className="px-4 py-8 text-center text-slate-400">No income recorded</td></tr>}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/db/prisma";
import { getCurrentUser } from "@/lib/auth/current-user";

export async function DELETE(_req: Request, ctx: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  const { id } = await ctx.params;
  const income = await prisma.income.findUnique({ where: { id } });
  if (!income) return NextResponse.json({ error: { message: "Not found" } }, { status: 404 });
  const membership = await prisma.householdMember.findFirst({ where: { userId: user.id, householdId: income.householdId } });
  if (!membership) return NextResponse.json({ error: { message: "Forbidden" } }, { status: 403 });
  await prisma.income.delete({ where: { id } });
  return NextResponse.json({ success: true });
}

