import { NextResponse } from "next/server";
import { prisma } from "@/lib/db/prisma";
import { getCurrentUser } from "@/lib/auth/current-user";

export async function POST(_req: Request, ctx: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  const { id } = await ctx.params;
  const exp = await prisma.expense.findUnique({ where: { id } });
  if (!exp) return NextResponse.json({ error: { message: "Not found" } }, { status: 404 });
  const membership = await prisma.householdMember.findFirst({ where: { userId: user.id, householdId: exp.householdId } });
  if (!membership) return NextResponse.json({ error: { message: "Forbidden" } }, { status: 403 });
  const dup = await prisma.expense.create({
    data: {
      householdId: exp.householdId,
      userId: user.id,
      categoryId: exp.categoryId,
      amount: exp.amount,
      currency: exp.currency,
      date: new Date(),
      notes: exp.notes,
      merchant: exp.merchant,
      tags: exp.tags,
      paymentMethod: exp.paymentMethod,
      isRecurring: exp.isRecurring,
      recurringFreq: exp.recurringFreq,
      isFixed: exp.isFixed,
      isEssential: exp.isEssential,
    },
    include: { category: true },
  });
  return NextResponse.json({ success: true, data: dup }, { status: 201 });
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/db/prisma";
import { getCurrentUser } from "@/lib/auth/current-user";
import { z } from "zod";

export async function POST(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  const body = await req.json().catch(() => ({}));
  const ids = z.array(z.string()).min(1).safeParse(body?.ids);
  if (!ids.success) return NextResponse.json({ error: { message: "ids required" } }, { status: 400 });
  // verify all belong to user's households
  const exps = await prisma.expense.findMany({ where: { id: { in: ids.data } } });
  const householdIds = new Set(exps.map((e) => e.householdId));
  for (const hid of householdIds) {
    const m = await prisma.householdMember.findFirst({ where: { userId: user.id, householdId: hid } });
    if (!m) return NextResponse.json({ error: { message: "Forbidden" } }, { status: 403 });
  }
  const res = await prisma.expense.deleteMany({ where: { id: { in: ids.data } } });
  return NextResponse.json({ success: true, data: { deleted: res.count } });
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/db/prisma";
import { getCurrentUser } from "@/lib/auth/current-user";

export async function POST(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  const body = await req.json().catch(() => ({}));
  const csv: string = body?.csv ?? "";
  const householdId: string = body?.householdId;
  if (!csv || !householdId) return NextResponse.json({ error: { message: "csv and householdId required" } }, { status: 400 });
  const membership = await prisma.householdMember.findFirst({ where: { userId: user.id, householdId } });
  if (!membership) return NextResponse.json({ error: { message: "Forbidden" } }, { status: 403 });

  const lines = csv.trim().split(/\r?\n/);
  if (lines.length < 2) return NextResponse.json({ error: { message: "No data rows" } }, { status: 400 });
  const header = lines[0].split(",").map((h) => h.trim().toLowerCase().replace(/"/g, ""));
  const idx = (name: string) => header.indexOf(name);

  let created = 0;
  const errors: string[] = [];
  for (let i = 1; i < lines.length; i++) {
    const cols = lines[i].split(",").map((c) => c.trim().replace(/^"|"$/g, ""));
    try {
      const date = cols[idx("date")] || new Date().toISOString().slice(0, 10);
      const amount = Number(cols[idx("amount")]);
      if (!amount || isNaN(amount)) { errors.push(`row ${i}: invalid amount`); continue; }
      const catName = cols[idx("category")] || "Miscellaneous";
      let cat = await prisma.category.findFirst({ where: { householdId, name: catName } });
      if (!cat) cat = await prisma.category.findFirst({ where: { householdId: null, name: catName } });
      if (!cat) {
        const slug = catName.toLowerCase().replace(/[^a-z0-9]+/g, "-");
        cat = await prisma.category.create({ data: { householdId, name: catName, slug: slug + "-" + Date.now(), color: "#94a3b8", icon: "tag", isDefault: false, type: "EXPENSE" } });
      }
      await prisma.expense.create({
        data: {
          householdId,
          userId: user.id,
          categoryId: cat.id,
          amount,
          date: new Date(date),
          notes: idx("notes") >= 0 ? cols[idx("notes")] || null : null,
          merchant: idx("merchant") >= 0 ? cols[idx("merchant")] || null : null,
          paymentMethod: (idx("paymentmethod") >= 0 ? cols[idx("paymentmethod")] : "CASH") as never,
        },
      });
      created++;
    } catch (e) {
      errors.push(`row ${i}: ${e instanceof Error ? e.message : "error"}`);
    }
  }
  return NextResponse.json({ success: true, data: { created, errors } });
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/db/prisma";
import { getCurrentUser } from "@/lib/auth/current-user";
import { z } from "zod";

const schema = z.object({
  householdId: z.string().min(1),
  amount: z.coerce.number().positive(),
  date: z.string().min(1),
  fromAccount: z.string().max(80).optional().or(z.literal("")),
  toAccount: z.string().max(80).optional().or(z.literal("")),
  notes: z.string().max(500).optional().or(z.literal("")),
});

export async function GET(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  const url = new URL(req.url);
  const householdId = url.searchParams.get("householdId");
  if (!householdId) return NextResponse.json({ error: { message: "householdId required" } }, { status: 400 });
  const membership = await prisma.householdMember.findFirst({ where: { userId: user.id, householdId } });
  if (!membership) return NextResponse.json({ error: { message: "Forbidden" } }, { status: 403 });
  const transfers = await prisma.transfer.findMany({ where: { householdId }, orderBy: { date: "desc" }, take: 200 });
  return NextResponse.json({ success: true, data: transfers });
}

export async function POST(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  try {
    const data = schema.parse(await req.json());
    const membership = await prisma.householdMember.findFirst({ where: { userId: user.id, householdId: data.householdId } });
    if (!membership) return NextResponse.json({ error: { message: "Forbidden" } }, { status: 403 });
    const t = await prisma.transfer.create({
      data: {
        householdId: data.householdId,
        userId: user.id,
        amount: data.amount,
        date: new Date(data.date),
        fromAccount: data.fromAccount || null,
        toAccount: data.toAccount || null,
        notes: data.notes || null,
      },
    });
    return NextResponse.json({ success: true, data: t }, { status: 201 });
  } catch (err) {
    return NextResponse.json({ error: { message: err instanceof Error ? err.message : "Invalid" } }, { status: 400 });
  }
}

