import { NextResponse } from "next/server";
import { prisma } from "@/lib/db/prisma";
import { getCurrentUser } from "@/lib/auth/current-user";

export async function GET(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  if (user.plan !== "PREMIUM") return NextResponse.json({ error: { message: "Premium required" } }, { status: 403 });
  const url = new URL(req.url);
  const householdId = url.searchParams.get("householdId");
  if (!householdId) return NextResponse.json({ error: { message: "householdId required" } }, { status: 400 });
  const membership = await prisma.householdMember.findFirst({ where: { userId: user.id, householdId } });
  if (!membership) return NextResponse.json({ error: { message: "Forbidden" } }, { status: 403 });

  const now = new Date();
  const months = 6;
  const monthly: number[] = [];
  for (let i = months - 1; i >= 0; i--) {
    const s = new Date(now.getFullYear(), now.getMonth() - i, 1);
    const e = new Date(now.getFullYear(), now.getMonth() - i + 1, 0, 23, 59, 59);
    const ex = await prisma.expense.findMany({ where: { householdId, date: { gte: s, lte: e } } });
    monthly.push(ex.reduce((x, y) => x + Number(y.amount), 0));
  }
  const avg = monthly.reduce((a, b) => a + b, 0) / monthly.length;
  const recurring = await prisma.expense.findMany({ where: { householdId, isRecurring: true } });
  const recurringTotal = recurring.reduce((s, e) => s + Number(e.amount), 0);
  const projectedNextMonth = avg * 0.6 + recurringTotal * 0.4 + recurringTotal;
  const projectedNextYear = avg * 12;

  return NextResponse.json({
    success: true,
    data: {
      monthlyHistory: monthly,
      averageMonthly: avg,
      recurringTotal,
      recurringCount: recurring.length,
      projectedNextMonth: Math.round(projectedNextMonth),
      projectedNextYear: Math.round(projectedNextYear),
      note: "Estimates based on historical spending and recurring bills. Actual results may vary.",
    },
  });
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/db/prisma";
import { getCurrentUser } from "@/lib/auth/current-user";
import { z } from "zod";

const schema = z.object({
  householdId: z.string().min(1),
  rentIncreasePct: z.coerce.number().default(0),
  electricityIncreasePct: z.coerce.number().default(0),
  newLoanEmi: z.coerce.number().default(0),
  months: z.coerce.number().int().min(1).max(24).default(12),
});

export async function POST(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  if (user.plan !== "PREMIUM") return NextResponse.json({ error: { message: "Premium required" } }, { status: 403 });
  try {
    const data = schema.parse(await req.json());
    const membership = await prisma.householdMember.findFirst({ where: { userId: user.id, householdId: data.householdId } });
    if (!membership) return NextResponse.json({ error: { message: "Forbidden" } }, { status: 403 });

    const now = new Date();
    const s = new Date(now.getFullYear(), now.getMonth(), 1);
    const e = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59);
    const exps = await prisma.expense.findMany({ where: { householdId: data.householdId, date: { gte: s, lte: e } }, include: { category: true } });
    const current = exps.reduce((x, y) => x + Number(y.amount), 0);

    // identify rent and electricity-ish categories
    const rent = exps.filter((x) => /rent|housing/i.test(x.category.name)).reduce((x, y) => x + Number(y.amount), 0);
    const elec = exps.filter((x) => /electric|utilit/i.test(x.category.name)).reduce((x, y) => x + Number(y.amount), 0);
    const other = current - rent - elec;

    const newRent = rent * (1 + data.rentIncreasePct / 100);
    const newElec = elec * (1 + data.electricityIncreasePct / 100);
    const adjusted = newRent + newElec + other + data.newLoanEmi;

    return NextResponse.json({
      success: true,
      data: {
        currentMonthly: current,
        adjustedMonthly: Math.round(adjusted),
        delta: Math.round(adjusted - current),
        breakdown: { rent: Math.round(newRent), electricity: Math.round(newElec), other: Math.round(other), newLoan: data.newLoanEmi },
        projectedOverMonths: Math.round(adjusted * data.months),
        note: "Estimate based on current month's spending. Forecasts are estimates.",
      },
    });
  } catch (err) {
    return NextResponse.json({ error: { message: err instanceof Error ? err.message : "Invalid" } }, { status: 400 });
  }
}

