  try {
    const data = schema.parse(await req.json());
    const membership = await prisma.householdMember.findFirst({ where: { userId: user.id, householdId: data.householdId } });
    if (!membership) return NextResponse.json({ error: { message: "Forbidden" } }, { status: 403 });

    const now = new Date();
    const s = new Date(now.getFullYear(), now.getMonth(), 1);
    const e = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59);
    const prevS = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    const prevE = new Date(now.getFullYear(), now.getMonth(), 0, 23, 59, 59);
    const exps = await prisma.expense.findMany({ where: { householdId: data.householdId, date: { gte: s, lte: e } }, include: { category: true } });
    const prevExps = await prisma.expense.findMany({ where: { householdId: data.householdId, date: { gte: prevS, lte: prevE } }, include: { category: true } });
    const total = exps.reduce((x, y) => x + Number(y.amount), 0);
    const prevTotal = prevExps.reduce((x, y) => x + Number(y.amount), 0);

    const byCat: Record<string, number> = {};
    for (const ex of exps) byCat[ex.category.name] = (byCat[ex.category.name] ?? 0) + Number(ex.amount);
    const topCat = Object.entries(byCat).sort((a, b) => b[1] - a[1])[0];

    const q = data.question.toLowerCase();
    let answer = "";
    if (q.includes("increase") || q.includes("why")) {
      const diff = total - prevTotal;
      answer = diff >= 0
        ? `Your spending increased by ₹${diff.toLocaleString()} compared to last month (₹${prevTotal.toLocaleString()} → ₹${total.toLocaleString()}). `
        : `Your spending decreased by ₹${Math.abs(diff).toLocaleString()} compared to last month. `;
      if (topCat) answer += `Top category this month: ${topCat[0]} (₹${topCat[1].toLocaleString()}).`;
    } else if (q.includes("top") || q.includes("category")) {
      answer = topCat ? `Your top spending category this month is ${topCat[0]} at ₹${topCat[1].toLocaleString()}.` : "No expenses recorded this month.";
      answer += " Breakdown: " + Object.entries(byCat).map(([k, v]) => `${k} ₹${v.toLocaleString()}`).join(", ") + ".";
    } else if (q.includes("saving")) {
      const incomes = await prisma.income.findMany({ where: { householdId: data.householdId, date: { gte: s, lte: e } } });
      const inc = incomes.reduce((x, y) => x + Number(y.amount), 0);
      answer = `Income: ₹${inc.toLocaleString()}, Expenses: ₹${total.toLocaleString()}, Savings: ₹${(inc - total).toLocaleString()}.`;
    } else if (q.includes("recurring")) {
      const rec = exps.filter((x) => x.isRecurring);
      answer = `You have ${rec.length} recurring expenses this month totalling ₹${rec.reduce((x, y) => x + Number(y.amount), 0).toLocaleString()}.`;
    } else if (q.includes("budget")) {
      answer = `Total spent this month: ₹${total.toLocaleString()} across ${exps.length} transactions. Set budgets on the Budgets page to track limits.`;
    } else {
      answer = `This month: ₹${total.toLocaleString()} spent across ${exps.length} transactions. Top category: ${topCat ? topCat[0] + " (₹" + topCat[1].toLocaleString() + ")" : "none"}. Ask about increases, top categories, savings, recurring bills, or budgets.`;
    }

    return NextResponse.json({ success: true, data: { answer, disclaimer: "AI-style insights derived from your actual transactions. Forecasts are estimates." } });
  } catch (err) {
    return NextResponse.json({ error: { message: err instanceof Error ? err.message : "Invalid" } }, { status: 400 });
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/db/prisma";
import { getCurrentUser } from "@/lib/auth/current-user";

export async function GET(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  if (user.plan !== "PREMIUM") return NextResponse.json({ error: { message: "Premium required" } }, { status: 403 });
  const url = new URL(req.url);
  const householdId = url.searchParams.get("householdId");
  if (!householdId) return NextResponse.json({ error: { message: "householdId required" } }, { status: 400 });
  const membership = await prisma.householdMember.findFirst({ where: { userId: user.id, householdId } });
  if (!membership) return NextResponse.json({ error: { message: "Forbidden" } }, { status: 403 });

  const now = new Date();
  const s = new Date(now.getFullYear(), now.getMonth(), 1);
  const e = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59);
  const exps = await prisma.expense.findMany({ where: { householdId, date: { gte: s, lte: e } }, include: { user: { select: { id: true, name: true, email: true } } } });

  const byMember: Record<string, { name: string; email: string; amount: number; count: number }> = {};
  for (const ex of exps) {
    const key = ex.userId;
    if (!byMember[key]) byMember[key] = { name: ex.user.name ?? ex.user.email, email: ex.user.email, amount: 0, count: 0 };
    byMember[key].amount += Number(ex.amount);
    byMember[key].count += 1;
  }
  const members = Object.values(byMember).sort((a, b) => b.amount - a.amount);
  const total = exps.reduce((x, y) => x + Number(y.amount), 0);
  return NextResponse.json({ success: true, data: { members, total, month: now.getMonth() + 1, year: now.getFullYear() } });
}

"use client";
import { useEffect, useState } from "react";

interface Household { id: string; name: string; }

export default function PremiumView() {
  const [households, setHouseholds] = useState<Household[]>([]);
  const [active, setActive] = useState("");
  const [isPremium, setIsPremium] = useState<boolean | null>(null);
  const [tab, setTab] = useState("predict");
  const [predict, setPredict] = useState<any>(null);
  const [whatif, setWhatif] = useState<any>(null);
  const [analystQ, setAnalystQ] = useState("");
  const [analystA, setAnalystA] = useState("");
  const [members, setMembers] = useState<any>(null);
  const [form, setForm] = useState({ rentIncreasePct: 0, electricityIncreasePct: 0, newLoanEmi: 0, months: 12 });

  useEffect(() => {
    (async () => {
      const h = await fetch("/api/households").then((r) => r.json());
      const list = h.data ?? [];
      setHouseholds(list);
      if (list.length) setActive(list[0].id);
      const me = await fetch("/api/auth/me").then((r) => r.json());
      setIsPremium(me?.data?.plan === "PREMIUM");
    })();
  }, []);
  useEffect(() => { if (active && isPremium) { loadPredict(); loadMembers(); } }, [active, isPremium]);

  async function loadPredict() {
    const r = await fetch(`/api/premium/predict?householdId=${active}`).then((r) => r.json());
    setPredict(r.data);
  }
  async function loadMembers() {
    const r = await fetch(`/api/premium/members?householdId=${active}`).then((r) => r.json());
    setMembers(r.data);
  }
  async function runWhatIf() {
    const r = await fetch("/api/premium/whatif", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ householdId: active, ...form }) }).then((r) => r.json());
    setWhatif(r.data);
  }
  async function runAnalyst() {
    const r = await fetch("/api/premium/analyst", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ householdId: active, question: analystQ }) }).then((r) => r.json());
    setAnalystA(r?.data?.answer ?? r?.error?.message ?? "No answer");
  }

  if (isPremium === null) return <div className="p-8 text-slate-500">Loading...</div>;
  if (!isPremium) {
    return (
      <div className="space-y-6">
        <h1 className="text-2xl font-bold">Premium Tools</h1>
        <div className="rounded-2xl bg-amber-50 p-8 text-center">
          <div className="text-lg font-semibold text-amber-800">Premium subscription required</div>
          <p className="mt-2 text-sm text-amber-700">Upgrade to access AI analyst, expense predictor, what-if simulator, and member analytics.</p>
          <a href="/settings" className="mt-4 inline-block rounded-lg bg-amber-500 px-4 py-2 text-sm font-medium text-white">Upgrade now</a>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <h1 className="text-2xl font-bold">Premium Tools</h1>
        <select value={active} onChange={(e) => setActive(e.target.value)} className="rounded-lg border px-3 py-2 text-sm">
          {households.map((h) => <option key={h.id} value={h.id}>{h.name}</option>)}
        </select>
      </div>
      <div className="flex flex-wrap gap-2">
        {["predict", "whatif", "analyst", "members"].map((t) => (
          <button key={t} onClick={() => setTab(t)} className={`rounded-lg px-4 py-2 text-sm font-medium ${tab === t ? "bg-indigo-600 text-white" : "border"}`}>
            {t === "predict" ? "Predictor" : t === "whatif" ? "What-If" : t === "analyst" ? "AI Analyst" : "Member Analytics"}
          </button>
        ))}
      </div>

      {tab === "predict" && predict && (
        <div className="rounded-2xl bg-white p-6 shadow-sm space-y-3">
          <h2 className="font-semibold">Future Expense Predictor</h2>
          <div className="grid gap-4 sm:grid-cols-3">
            <Card title="Avg Monthly" value={`₹${predict.averageMonthly.toFixed(0)}`} />
            <Card title="Recurring Total" value={`₹${predict.recurringTotal.toLocaleString()}`} sub={`${predict.recurringCount} bills`} />
            <Card title="Projected Next Month" value={`₹${predict.projectedNextMonth.toLocaleString()}`} />
          </div>
          <div className="text-sm">Projected yearly: ₹{predict.projectedNextYear.toLocaleString()}</div>
          <div className="text-xs text-slate-500">{predict.note}</div>
          <div className="mt-2">
            <div className="text-xs font-medium text-slate-500 mb-1">Last 6 months</div>
            <div className="flex items-end gap-1 h-24">
              {predict.monthlyHistory.map((v: number, i: number) => {
                const max = Math.max(...predict.monthlyHistory, 1);
                return <div key={i} className="flex-1 rounded-t bg-indigo-400" style={{ height: `${(v / max) * 100}%`, minHeight: v ? 2 : 0 }} title={`₹${v}`} />;
              })}
            </div>
          </div>
        </div>
      )}

      {tab === "whatif" && (
        <div className="rounded-2xl bg-white p-6 shadow-sm space-y-4">
          <h2 className="font-semibold">What-If Expense Simulator</h2>
          <div className="grid gap-4 sm:grid-cols-2">
            <div><label className="text-sm">Rent increase %</label><input type="number" value={form.rentIncreasePct} onChange={(e) => setForm({ ...form, rentIncreasePct: Number(e.target.value) })} className="mt-1 w-full rounded-lg border px-3 py-2" /></div>
            <div><label className="text-sm">Electricity increase %</label><input type="number" value={form.electricityIncreasePct} onChange={(e) => setForm({ ...form, electricityIncreasePct: Number(e.target.value) })} className="mt-1 w-full rounded-lg border px-3 py-2" /></div>
            <div><label className="text-sm">New loan EMI (₹)</label><input type="number" value={form.newLoanEmi} onChange={(e) => setForm({ ...form, newLoanEmi: Number(e.target.value) })} className="mt-1 w-full rounded-lg border px-3 py-2" /></div>
            <div><label className="text-sm">Months</label><input type="number" value={form.months} onChange={(e) => setForm({ ...form, months: Number(e.target.value) })} className="mt-1 w-full rounded-lg border px-3 py-2" /></div>
          </div>
          <button onClick={runWhatIf} className="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-medium text-white">Simulate</button>
          {whatif && (
            <div className="mt-4 space-y-2 text-sm">
              <div>Current monthly: ₹{whatif.currentMonthly.toLocaleString()}</div>
              <div className="font-semibold">Adjusted monthly: ₹{whatif.adjustedMonthly.toLocaleString()} (Δ ₹{whatif.delta.toLocaleString()})</div>
              <div>Over {form.months} months: ₹{whatif.projectedOverMonths.toLocaleString()}</div>
              <div className="text-xs text-slate-500">{whatif.note}</div>
            </div>
          )}
        </div>
      )}

      {tab === "analyst" && (
        <div className="rounded-2xl bg-white p-6 shadow-sm space-y-4">
          <h2 className="font-semibold">AI Expense Analyst</h2>
          <div className="flex gap-2">
            <input value={analystQ} onChange={(e) => setAnalystQ(e.target.value)} placeholder="e.g. Why did my expenses increase this month?" className="flex-1 rounded-lg border px-3 py-2 text-sm" />
            <button onClick={runAnalyst} className="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-medium text-white">Ask</button>
          </div>
          {analystA && <div className="rounded-lg bg-slate-50 p-4 text-sm">{analystA}</div>}
        </div>
      )}

      {tab === "members" && members && (
        <div className="rounded-2xl bg-white p-6 shadow-sm space-y-3">
          <h2 className="font-semibold">Member-Level Analytics ({members.month}/{members.year})</h2>
          <div className="text-sm">Total: ₹{members.total.toLocaleString()}</div>
          <ul className="divide-y">
            {members.members.map((m: any) => (
              <li key={m.email} className="flex items-center justify-between py-2 text-sm">
                <span>{m.name} <span className="text-slate-400">({m.count} txns)</span></span>
                <span className="font-medium">₹{m.amount.toLocaleString()} ({members.total ? ((m.amount / members.total) * 100).toFixed(1) : 0}%)</span>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}

function Card({ title, value, sub }: { title: string; value: any; sub?: string }) {
  return (
    <div className="rounded-2xl bg-white p-5 shadow-sm">
      <div className="text-xs font-medium uppercase text-slate-500">{title}</div>
      <div className="mt-2 text-2xl font-bold">{value}</div>
      {sub && <div className="mt-1 text-xs text-slate-400">{sub}</div>}
    </div>
  );
}

