import { NextResponse } from "next/server";
import { prisma } from "@/lib/db/prisma";
import { getCurrentUser } from "@/lib/auth/current-user";
import { z } from "zod";

const schema = z.object({
  householdId: z.string().min(1),
  name: z.string().min(1).max(80),
  targetAmount: z.coerce.number().positive(),
  currentAmount: z.coerce.number().min(0).optional(),
  deadline: z.string().optional().or(z.literal("")),
});

export async function GET(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  const url = new URL(req.url);
  const householdId = url.searchParams.get("householdId");
  if (!householdId) return NextResponse.json({ error: { message: "householdId required" } }, { status: 400 });
  const membership = await prisma.householdMember.findFirst({ where: { userId: user.id, householdId } });
  if (!membership) return NextResponse.json({ error: { message: "Forbidden" } }, { status: 403 });
  const goals = await prisma.financialGoal.findMany({ where: { householdId }, orderBy: { createdAt: "desc" } });
  return NextResponse.json({ success: true, data: goals });
}

export async function POST(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  try {
    const data = schema.parse(await req.json());
    const membership = await prisma.householdMember.findFirst({ where: { userId: user.id, householdId: data.householdId } });
    if (!membership) return NextResponse.json({ error: { message: "Forbidden" } }, { status: 403 });
    const goal = await prisma.financialGoal.create({
      data: {
        householdId: data.householdId,
        userId: user.id,
        name: data.name,
        targetAmount: data.targetAmount,
        currentAmount: data.currentAmount ?? 0,
        deadline: data.deadline ? new Date(data.deadline) : null,
      },
    });
    return NextResponse.json({ success: true, data: goal }, { status: 201 });
  } catch (err) {
    return NextResponse.json({ error: { message: err instanceof Error ? err.message : "Invalid" } }, { status: 400 });
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/db/prisma";
import { getCurrentUser } from "@/lib/auth/current-user";

export async function GET() {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  const notes = await prisma.notification.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, take: 50 });
  return NextResponse.json({ success: true, data: notes });
}

export async function POST(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  const body = await req.json().catch(() => ({}));
  const n = await prisma.notification.create({ data: { userId: user.id, title: body.title ?? "Notification", body: body.body ?? null } });
  return NextResponse.json({ success: true, data: n }, { status: 201 });
}

export async function PATCH(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  const body = await req.json().catch(() => ({}));
  if (body?.markAllRead) {
    await prisma.notification.updateMany({ where: { userId: user.id }, data: { read: true } });
  }
  if (body?.id) {
    await prisma.notification.updateMany({ where: { id: body.id, userId: user.id }, data: { read: true } });
  }
  return NextResponse.json({ success: true });
}

"use client";
import { useEffect, useState } from "react";

interface Household { id: string; name: string; }
interface Category { id: string; name: string; color: string; isDefault: boolean; householdId: string | null; }

export default function CategoriesView() {
  const [households, setHouseholds] = useState<Household[]>([]);
  const [active, setActive] = useState("");
  const [categories, setCategories] = useState<Category[]>([]);
  const [name, setName] = useState("");

  useEffect(() => {
    (async () => {
      const h = await fetch("/api/households").then((r) => r.json());
      const list = h.data ?? [];
      setHouseholds(list);
      if (list.length) setActive(list[0].id);
    })();
  }, []);
  useEffect(() => { if (active) load(); }, [active]);
  async function load() {
    const c = await fetch(`/api/categories?householdId=${active}`).then((r) => r.json());
    setCategories(c.data ?? []);
  }
  async function add(e: React.FormEvent) {
    e.preventDefault();
    if (!name) return;
    await fetch("/api/categories", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ householdId: active, name }) });
    setName(""); load();
  }
  async function remove(id: string) {
    await fetch(`/api/categories/${id}`, { method: "DELETE" }).catch(() => {});
    load();
  }

  if (!households.length) return <div className="p-8">No household.</div>;

  const custom = categories.filter((c) => !c.isDefault && c.householdId === active);
  const defaults = categories.filter((c) => c.isDefault || c.householdId !== active);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold">Categories</h1>
        <select value={active} onChange={(e) => setActive(e.target.value)} className="rounded-lg border px-3 py-2 text-sm">
          {households.map((h) => <option key={h.id} value={h.id}>{h.name}</option>)}
        </select>
      </div>
      <div className="rounded-2xl bg-white p-6 shadow-sm">
        <h2 className="mb-4 font-semibold">Add Custom Category</h2>
        <form onSubmit={add} className="flex gap-2">
          <input value={name} onChange={(e) => setName(e.target.value)} placeholder="Category name" className="flex-1 rounded-lg border px-3 py-2 text-sm" />
          <button className="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-medium text-white">Add</button>
        </form>
      </div>
      <div className="grid gap-6 lg:grid-cols-2">
        <div className="rounded-2xl bg-white p-6 shadow-sm">
          <h2 className="mb-4 font-semibold">Custom Categories ({custom.length})</h2>
          <ul className="space-y-2">
            {custom.map((c) => (
              <li key={c.id} className="flex items-center justify-between text-sm">
                <span className="flex items-center gap-2"><span className="h-2 w-2 rounded-full" style={{ background: c.color }} />{c.name}</span>
                <button onClick={() => remove(c.id)} className="text-red-600 hover:underline">Delete</button>
              </li>
            ))}
            {custom.length === 0 && <li className="text-slate-400">None yet</li>}
          </ul>
        </div>
        <div className="rounded-2xl bg-white p-6 shadow-sm">
          <h2 className="mb-4 font-semibold">Default Categories ({defaults.length})</h2>
          <ul className="space-y-1 text-sm text-slate-600 max-h-96 overflow-y-auto">
            {defaults.map((c) => <li key={c.id} className="flex items-center gap-2"><span className="h-2 w-2 rounded-full" style={{ background: c.color }} />{c.name}</li>)}
          </ul>
        </div>
      </div>
    </div>
  );
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/db/prisma";
import { getCurrentUser } from "@/lib/auth/current-user";

export async function DELETE(_req: Request, ctx: { params: Promise<{ id: string }> }) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  const { id } = await ctx.params;
  const cat = await prisma.category.findUnique({ where: { id } });
  if (!cat) return NextResponse.json({ error: { message: "Not found" } }, { status: 404 });
  if (cat.isDefault) return NextResponse.json({ error: { message: "Cannot delete default category" } }, { status: 400 });
  if (cat.householdId) {
    const membership = await prisma.householdMember.findFirst({ where: { userId: user.id, householdId: cat.householdId } });
    if (!membership) return NextResponse.json({ error: { message: "Forbidden" } }, { status: 403 });
  }
  await prisma.category.delete({ where: { id } });
  return NextResponse.json({ success: true });
}

