const buckets = new Map<string, { count: number; resetAt: number }>();

export function proxy(request: NextRequest) {
  const ip = request.headers.get("x-forwarded-for")?.split(",")[0]?.trim() || "unknown";
  const key = `${ip}:${request.nextUrl.pathname}`;
  const now = Date.now();
  const windowMs = 60_000;
  const limit = 120;
  let entry = buckets.get(key);
  if (!entry || entry.resetAt <= now) {
    entry = { count: 1, resetAt: now + windowMs };
    buckets.set(key, entry);
  } else {
    entry.count += 1;
  }
  if (entry.count > limit) {
    return new NextResponse(JSON.stringify({ error: { message: "Too many requests" } }), {
      status: 429,
      headers: { "Content-Type": "application/json", "Retry-After": String(Math.ceil((entry.resetAt - now) / 1000)) },
    });
  }

  const incoming = request.headers.get(REQUEST_ID_HEADER);
  const requestId = incoming && /^[A-Za-z0-9_-]{8,128}$/.test(incoming) ? incoming : crypto.randomUUID();
  const requestHeaders = new Headers(request.headers);
  requestHeaders.set(REQUEST_ID_HEADER, requestId);

  const response = NextResponse.next({ request: { headers: requestHeaders } });
  response.headers.set(REQUEST_ID_HEADER, requestId);
  return response;
}

