import "server-only";

export interface Logger {
  info: (...args: unknown[]) => void;
  warn: (...args: unknown[]) => void;
  error: (...args: unknown[]) => void;
  debug: (...args: unknown[]) => void;
  child: (ctx: Record<string, unknown>) => Logger;
}

function makeLogger(ctx: Record<string, unknown> = {}): Logger {
  const log = (level: string, ...args: unknown[]) => {
    // eslint-disable-next-line no-console
    console.log(JSON.stringify({ level, ...ctx, ...args.reduce((a, b) => (typeof b === "object" ? { ...a, ...(b as object) } : a), {}) }));
  };
  const self: Logger = {
    info: (...a) => log("info", ...a),
    warn: (...a) => log("warn", ...a),
    error: (...a) => log("error", ...a),
    debug: (...a) => log("debug", ...a),
    child: (c) => makeLogger({ ...ctx, ...c }),
  };
  return self;
}

export const logger = makeLogger({ service: "homewise" });

export function createRequestLogger(requestId: string, context: Record<string, unknown> = {}): Logger {
  return logger.child({ requestId, ...context });
}

