import { NextResponse } from "next/server";
import { prisma } from "@/lib/db/prisma";
import { getCurrentUser } from "@/lib/auth/current-user";

export async function POST(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  const body = await req.json().catch(() => ({}));
  const householdId = body?.householdId;
  if (!householdId) return NextResponse.json({ error: { message: "householdId required" } }, { status: 400 });
  const membership = await prisma.householdMember.findFirst({ where: { userId: user.id, householdId } });
  if (!membership) return NextResponse.json({ error: { message: "Forbidden" } }, { status: 403 });

  const now = new Date();
  const s = new Date(now.getFullYear(), now.getMonth(), 1);
  const e = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59);
  const created: string[] = [];

  async function notify(title: string, message: string) {
    // avoid duplicate within 24h
    const recent = await prisma.notification.findFirst({ where: { userId: user.id, title, createdAt: { gte: new Date(Date.now() - 24 * 60 * 60 * 1000) } } });
    if (recent) return;
    await prisma.notification.create({ data: { userId: user.id, title, body: message } });
    created.push(title);
  }

  // Budgets
  const budgets = await prisma.budget.findMany({ where: { householdId, year: now.getFullYear(), month: now.getMonth() + 1 }, include: { category: true } });
  const expenses = await prisma.expense.findMany({ where: { householdId, date: { gte: s, lte: e } } });
  const total = expenses.reduce((x, y) => x + Number(y.amount), 0);
  const byCat: Record<string, number> = {};
  for (const ex of expenses) byCat[ex.categoryId] = (byCat[ex.categoryId] ?? 0) + Number(ex.amount);
  for (const b of budgets) {
    const spent = b.categoryId ? (byCat[b.categoryId] ?? 0) : total;
    const pct = Number(b.amount) > 0 ? (spent / Number(b.amount)) * 100 : 0;
    if (pct >= 100) await notify(`Budget exceeded: ${b.category?.name ?? "Overall"}`, `You've spent ₹${spent.toLocaleString()} of ₹${Number(b.amount).toLocaleString()} (${pct.toFixed(0)}%).`);
    else if (pct >= 80) await notify(`Budget at 80%: ${b.category?.name ?? "Overall"}`, `You've spent ₹${spent.toLocaleString()} of ₹${Number(b.amount).toLocaleString()} (${pct.toFixed(0)}%).`);
    else if (pct >= 50) await notify(`Budget at 50%: ${b.category?.name ?? "Overall"}`, `You've spent ₹${spent.toLocaleString()} of ₹${Number(b.amount).toLocaleString()} (${pct.toFixed(0)}%).`);
  }

  // Unusual spending
  const prevMonths: number[] = [];
  for (let i = 1; i <= 3; i++) {
    const ps = new Date(now.getFullYear(), now.getMonth() - i, 1);
    const pe = new Date(now.getFullYear(), now.getMonth() - i + 1, 0, 23, 59, 59);
    const ex = await prisma.expense.findMany({ where: { householdId, date: { gte: ps, lte: pe } } });
    prevMonths.push(ex.reduce((x, y) => x + Number(y.amount), 0));
  }
  const avg = prevMonths.reduce((a, b) => a + b, 0) / (prevMonths.length || 1);
  if (avg > 0 && total > avg * 1.5) {
    await notify("Unusual spending detected", `This month's spending (₹${total.toLocaleString()}) is significantly higher than your 3-month average (₹${avg.toFixed(0)}).`);
  }

  // Financial goals progress
  const goals = await prisma.financialGoal.findMany({ where: { householdId } });
  for (const g of goals) {
    const pct = Number(g.targetAmount) > 0 ? (Number(g.currentAmount) / Number(g.targetAmount)) * 100 : 0;
    if (pct >= 100) await notify(`Goal reached: ${g.name}`, `You've reached your target of ₹${Number(g.targetAmount).toLocaleString()}!`);
    else if (pct >= 75) await notify(`Goal 75%: ${g.name}`, `${pct.toFixed(0)}% complete.`);
    else if (pct >= 50) await notify(`Goal 50%: ${g.name}`, `${pct.toFixed(0)}% complete.`);
    else if (pct >= 25) await notify(`Goal 25%: ${g.name}`, `${pct.toFixed(0)}% complete.`);
  }

  // Subscription renewal
  const subs = await prisma.subscription.findMany({ where: { userId: user.id, status: "ACTIVE" } });
  for (const sub of subs) {
    if (sub.currentPeriodEnd) {
      const days = (sub.currentPeriodEnd.getTime() - now.getTime()) / (1000 * 60 * 60 * 24);
      if (days <= 7 && days >= 0) await notify("Subscription renewal", `Your premium subscription renews on ${sub.currentPeriodEnd.toLocaleDateString()}.`);
    }
  }

  return NextResponse.json({ success: true, data: { created } });
}

