import { NextResponse } from "next/server";
import { prisma } from "@/lib/db/prisma";
import { getCurrentUser } from "@/lib/auth/current-user";
import * as XLSX from "xlsx";

export async function GET(req: Request) {
  const user = await getCurrentUser();
  if (!user) return NextResponse.json({ error: { message: "Unauthorized" } }, { status: 401 });
  const url = new URL(req.url);
  const householdId = url.searchParams.get("householdId");
  if (!householdId) return NextResponse.json({ error: { message: "householdId required" } }, { status: 400 });
  const membership = await prisma.householdMember.findFirst({ where: { userId: user.id, householdId } });
  if (!membership) return NextResponse.json({ error: { message: "Forbidden" } }, { status: 403 });

  const expenses = await prisma.expense.findMany({ where: { householdId, deletedAt: null }, include: { category: true }, orderBy: { date: "desc" } });
  const incomes = await prisma.income.findMany({ where: { householdId }, orderBy: { date: "desc" } });

  const expRows = expenses.map((e) => ({ Date: e.date.toISOString().slice(0, 10), Amount: Number(e.amount), Currency: e.currency, Category: e.category.name, PaymentMethod: e.paymentMethod, Merchant: e.merchant ?? "", Notes: e.notes ?? "", Fixed: e.isFixed, Essential: e.isEssential }));
  const incRows = incomes.map((i) => ({ Date: i.date.toISOString().slice(0, 10), Amount: Number(i.amount), Currency: i.currency, Source: i.source ?? "", Notes: i.notes ?? "" }));

  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(expRows), "Expenses");
  XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(incRows), "Income");
  const buf = XLSX.write(wb, { type: "buffer", bookType: "xlsx" });

  return new NextResponse(buf, {
    status: 200,
    headers: {
      "Content-Type": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      "Content-Disposition": `attachment; filename="homewise-${householdId}.xlsx"`,
    },
  });
}

"use client";
import { useEffect, useState } from "react";

export default function PrintReportPage() {
  const [households, setHouseholds] = useState<any[]>([]);
  const [active, setActive] = useState("");
  const [summary, setSummary] = useState<any>(null);

  useEffect(() => {
    (async () => {
      const h = await fetch("/api/households").then((r) => r.json());
      const list = h.data ?? [];
      setHouseholds(list);
      if (list.length) setActive(list[0].id);
    })();
  }, []);
  useEffect(() => {
    if (!active) return;
    const now = new Date();
    fetch(`/api/analytics/summary?householdId=${active}&year=${now.getFullYear()}&month=${now.getMonth() + 1}`).then((r) => r.json()).then((j) => setSummary(j.data));
  }, [active]);

  return (
    <div className="mx-auto max-w-4xl px-6 py-8">
      <div className="mb-4 flex gap-2 print:hidden">
        <select value={active} onChange={(e) => setActive(e.target.value)} className="rounded-lg border px-3 py-2 text-sm">
          {households.map((h: any) => <option key={h.id} value={h.id}>{h.name}</option>)}
        </select>
        <button onClick={() => window.print()} className="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-medium text-white">Print / Save as PDF</button>
      </div>
      <h1 className="text-2xl font-bold">Household Expense Report</h1>
      {summary && (
        <>
          <p className="text-sm text-slate-500">{summary.month}/{summary.year}</p>
          <div className="mt-4 grid gap-4 sm:grid-cols-3">
            <div className="rounded border p-3"><div className="text-xs text-slate-500">Total</div><div className="text-xl font-bold">₹{summary.total.toLocaleString()}</div></div>
            <div className="rounded border p-3"><div className="text-xs text-slate-500">Income</div><div className="text-xl font-bold">₹{summary.totalIncome.toLocaleString()}</div></div>
            <div className="rounded border p-3"><div className="text-xs text-slate-500">Savings</div><div className="text-xl font-bold">₹{summary.savings.toLocaleString()}</div></div>
          </div>
          <h2 className="mt-6 font-semibold">Category Breakdown</h2>
          <table className="mt-2 w-full text-sm border">
            <thead><tr className="border-b bg-slate-50"><th className="p-2 text-left">Category</th><th className="p-2 text-right">Amount</th><th className="p-2 text-right">Share</th></tr></thead>
            <tbody>
              {summary.byCategory.map((c: any) => (
                <tr key={c.name} className="border-b"><td className="p-2">{c.name}</td><td className="p-2 text-right">₹{c.amount.toLocaleString()}</td><td className="p-2 text-right">{summary.total ? ((c.amount / summary.total) * 100).toFixed(1) : 0}%</td></tr>
              ))}
            </tbody>
          </table>
          <h2 className="mt-6 font-semibold">Recent Transactions</h2>
          <table className="mt-2 w-full text-sm border">
            <thead><tr className="border-b bg-slate-50"><th className="p-2 text-left">Date</th><th className="p-2 text-left">Category</th><th className="p-2 text-right">Amount</th><th className="p-2 text-left">Notes</th></tr></thead>
            <tbody>
              {summary.recent.map((e: any) => (
                <tr key={e.id} className="border-b"><td className="p-2">{e.date.slice(0, 10)}</td><td className="p-2">{e.category}</td><td className="p-2 text-right">₹{e.amount.toLocaleString()}</td><td className="p-2">{e.notes}</td></tr>
              ))}
            </tbody>
          </table>
        </>
      )}
    </div>
  );
}

import { defineConfig } from "vitest/config";
import path from "path";

export default defineConfig({
  test: {
    environment: "node",
    include: ["tests/**/*.test.ts"],
  },
  resolve: {
    alias: { "@": path.resolve(__dirname, "./src") },
  },
});

export function totalExpenses(amounts: number[]): number {
  return amounts.reduce((a, b) => a + b, 0);
}
export function dailyAverage(total: number, days: number): number {
  return days > 0 ? total / days : 0;
}
export function monthlyAverage(total: number, months: number): number {
  return months > 0 ? total / months : 0;
}
export function categoryPercentage(categoryAmount: number, total: number): number {
  return total > 0 ? (categoryAmount / total) * 100 : 0;
}
export function remainingBudget(budget: number, spent: number): number {
  return budget - spent;
}
export function netCashFlow(income: number, expenses: number): number {
  return income - expenses;
}
export function savingsRate(savings: number, income: number): number {
  return income > 0 ? (savings / income) * 100 : 0;
}
export function yearlyProjection(avgMonthly: number): number {
  return avgMonthly * 12;
}
export function expenseGrowth(current: number, previous: number): number {
  if (previous === 0) return current > 0 ? 100 : 0;
  return ((current - previous) / previous) * 100;
}

import { describe, it, expect } from "vitest";
import { totalExpenses, dailyAverage, categoryPercentage, remainingBudget, netCashFlow, savingsRate, yearlyProjection, expenseGrowth } from "@/lib/calculations";

describe("calculations", () => {
  it("totalExpenses sums amounts", () => {
    expect(totalExpenses([10, 20, 30])).toBe(60);
    expect(totalExpenses([])).toBe(0);
  });
  it("dailyAverage", () => {
    expect(dailyAverage(300, 30)).toBe(10);
    expect(dailyAverage(100, 0)).toBe(0);
  });
  it("categoryPercentage", () => {
    expect(categoryPercentage(25, 100)).toBe(25);
    expect(categoryPercentage(10, 0)).toBe(0);
  });
  it("remainingBudget", () => {
    expect(remainingBudget(1000, 400)).toBe(600);
  });
  it("netCashFlow", () => {
    expect(netCashFlow(5000, 3000)).toBe(2000);
  });
  it("savingsRate", () => {
    expect(savingsRate(2000, 5000)).toBe(40);
    expect(savingsRate(100, 0)).toBe(0);
  });
  it("yearlyProjection", () => {
    expect(yearlyProjection(1000)).toBe(12000);
  });
  it("expenseGrowth", () => {
    expect(expenseGrowth(120, 100)).toBe(20);
    expect(expenseGrowth(100, 0)).toBe(100);
  });
});

